from solution import valid_date
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference(date):
    """Obviously-correct model derived directly from spec rules."""
    if not isinstance(date, str):
        return False
    if date == "":
        return False
    if len(date) != 10:
        return False
    if date[2] != "-" or date[5] != "-":
        return False
    m_s, d_s, y_s = date[:2], date[3:5], date[6:]
    if not (m_s.isdigit() and d_s.isdigit() and y_s.isdigit()):
        return False
    m = int(m_s)
    d = int(d_s)
    if not 1 <= m <= 12:
        return False
    if m in (1, 3, 5, 7, 8, 10, 12):
        max_d = 31
    elif m in (4, 6, 9, 11):
        max_d = 30
    else:
        max_d = 29
    if not 1 <= d <= max_d:
        return False
    return True


# ---- explicit spec examples ----
def test_spec_example_03_11_2000_true():
    assert valid_date('03-11-2000') is True


def test_spec_example_15_01_2012_false():
    assert valid_date('15-01-2012') is False


def test_spec_example_04_0_2040_false():
    assert valid_date('04-0-2040') is False


def test_spec_example_06_04_2020_true():
    assert valid_date('06-04-2020') is True


def test_spec_example_slash_separator_false():
    assert valid_date('06/04/2020') is False


def test_empty_string_is_invalid():
    assert valid_date('') is False


# ---- equivalence to reference model ----
@given(st.text(alphabet=st.sampled_from(list("0123456789-/abc :")) , max_size=12))
def test_equivalence_to_reference_model(s):
    assert valid_date(s) == reference(s)


@given(st.text(max_size=15))
def test_equivalence_to_reference_arbitrary_text(s):
    assert valid_date(s) == reference(s)


# ---- valid dates must be accepted ----
@given(
    m=st.integers(min_value=1, max_value=12),
    y=st.integers(min_value=0, max_value=9999),
)
def test_all_valid_month_day_combinations_accepted(m, y):
    if m in (1, 3, 5, 7, 8, 10, 12):
        max_d = 31
    elif m in (4, 6, 9, 11):
        max_d = 30
    else:
        max_d = 29
    for d in (1, max_d):
        s = f"{m:02d}-{d:02d}-{y:04d}"
        assert valid_date(s) is True, s


@given(y=st.integers(min_value=0, max_value=9999))
def test_boundary_days_per_month(y):
    ys = f"{y:04d}"
    # 31-day months accept 31
    for m in [1, 3, 5, 7, 8, 10, 12]:
        assert valid_date(f"{m:02d}-31-{ys}") is True
        assert valid_date(f"{m:02d}-32-{ys}") is False
        assert valid_date(f"{m:02d}-00-{ys}") is False
    # 30-day months reject 31
    for m in [4, 6, 9, 11]:
        assert valid_date(f"{m:02d}-30-{ys}") is True
        assert valid_date(f"{m:02d}-31-{ys}") is False
        assert valid_date(f"{m:02d}-00-{ys}") is False
    # Feb accepts 29 rejects 30
    assert valid_date(f"02-29-{ys}") is True
    assert valid_date(f"02-30-{ys}") is False
    assert valid_date(f"02-00-{ys}") is False


def test_day_zero_and_32_rejected_all_months():
    for m in range(1, 13):
        assert valid_date(f"{m:02d}-00-2000") is False
        assert valid_date(f"{m:02d}-32-2000") is False


def test_month_boundaries():
    assert valid_date("00-15-2000") is False
    assert valid_date("01-15-2000") is True
    assert valid_date("12-15-2000") is True
    assert valid_date("13-15-2000") is False
    assert valid_date("00-00-0000") is False


@given(m=st.integers(min_value=13, max_value=99))
def test_invalid_month_high_rejected(m):
    assert valid_date(f"{m:02d}-15-2000") is False


# ---- format mm-dd-yyyy strictly enforced ----
def test_format_must_be_mm_dd_yyyy_length_10():
    assert valid_date("3-11-2000") is False
    assert valid_date("03-1-2000") is False
    assert valid_date("03-11-00") is False
    assert valid_date("03-11-20000") is False
    assert valid_date("03-11-2000 ") is False
    assert valid_date(" 03-11-2000") is False
    assert valid_date("03-11-200") is False
    assert valid_date("03112000") is False
    assert valid_date("03--11-2000") is False


def test_wrong_separators_rejected():
    for sep in ["/", ".", ":", " ", "_"]:
        assert valid_date(f"06{sep}04{sep}2020") is False
    assert valid_date("06-04/2020") is False
    assert valid_date("06/04-2020") is False


def test_non_digit_components_rejected():
    assert valid_date("ab-cd-efgh") is False
    assert valid_date("0a-11-2000") is False
    assert valid_date("03-1a-2000") is False
    assert valid_date("03-11-20a0") is False
    assert valid_date("03-11-200 ") is False


@given(st.integers(min_value=0, max_value=9999))
def test_year_digits_do_not_affect_validity(y):
    # Spec: only month/day ranges + format matter; any 4-digit year ok.
    # Metamorphic: swapping year digits preserves result.
    base_valid = "06-04-2020"
    assert valid_date(base_valid) is True
    ys = f"{y:04d}"
    assert valid_date(f"06-04-{ys}") is True
    # invalid day stays invalid regardless of year
    assert valid_date(f"02-30-{ys}") is False
    assert valid_date(f"04-31-{ys}") is False


@given(
    m=st.integers(min_value=1, max_value=12),
    d=st.integers(min_value=1, max_value=29),
    y=st.integers(min_value=0, max_value=9999),
)
def test_leading_zero_format_valid(m, d, y):
    s = f"{m:02d}-{d:02d}-{y:04d}"
    # days 1..29 valid for every month per spec
    assert valid_date(s) is True
